package graph

// draftToolDeclarations are the tools that carry a draft, a problem or a human
// check, and the ones that control a task.
func draftToolDeclarations(set agentToolContext) []AgentToolDeclaration {
	main := set.main
	features := set.features
	return []AgentToolDeclaration{
		{Name: "confirm_draft", Label: "Confirm draft", Description: "Confirm only when the user explicitly asked; quote their words verbatim and use their target branch. proposalVersion and draftRevision must still match the draft.", Parameters: tbObject([]tbField{{"proposalVersion", tbNumber()}, {"draftRevision", tbNumber()}, {"targetBranch", tbString(nil)}, {"instruction", tbString(nil)}, {"requestId", tbString(nil)}}, []string{"proposalVersion", "draftRevision", "targetBranch", "instruction", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.ConfirmDraft},
		{Name: "list_problems", Label: "List execution problems", Description: "List the internal execution problems the main Agent owns. These are not user questions; inspect them before retrying, revising the graph or asking the user.", Parameters: tbObject(nil, nil), Available: main && features.Supervisor != nil && features.Supervisor.ListProblems && features.Supervisor.ResolveProblem},
		{Name: "resolve_problem", Label: "Resolve execution problem", Description: "Resolve main-owned problems: retry fixable failures, acknowledge cleared obstacles, respond to questions. Include expectedRevision from list_problems for routed questions. Reconcile usage only without authoritative provider data; escalate decisions only the user can make.", Parameters: tbObject([]tbField{{"questionId", tbString(nil)}, {"action", tbString(nil)}, {"response", tbOptional(tbString(nil))}, {"proof", tbOptional(tbString(nil))}, {"expectedRevision", tbOptional(tbNumber())}, {"requestId", tbString(nil)}}, []string{"questionId", "action", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.ListProblems && features.Supervisor.ResolveProblem},
		{Name: "ask_supervisor", Label: "Ask or notify your supervisor", Description: "Ask your supervisor when you cannot resolve a question yourself, or tell it what happened. kind=question explains what you tried and why the answer matters, and your turn waits for the answer. kind=notice reports a milestone (draft ready, completed, failed, blocked) with where the evidence lives: the receiver cannot open your task workspace, so name the artifact in artifactId and the delivery carries its excerpt, while an evidence that is only a pointer arrives marked as unattached; pass the work id and the notice is delivered once per work and milestone, so repeating it changes nothing. A notice does not wait: the global supervisor is woken with your text and your turn continues. kind, workId, milestone and evidence are optional; the default is kind=question.", Parameters: tbObject([]tbField{{"prompt", tbString(nil)}, {"why", tbOptional(tbString(nil))}, {"kind", tbOptional(tbString(nil))}, {"workId", tbOptional(tbString(nil))}, {"milestone", tbOptional(tbString(nil))}, {"evidence", tbOptional(tbString(nil))}, {"artifactId", tbOptional(tbString(nil))}, {"artifactVersion", tbOptional(tbNumber())}, {"options", tbOptional(tbArray(tbString(nil)))}, {"multiple", tbOptional(tbBool())}, {"requestId", tbString(nil)}}, []string{"prompt", "requestId"}), Available: features.AskSupervisor},
		{Name: "control_task", Label: "Control a task", Description: "Control the task you serve, or another task of the same conversation. pause soft-stops the turn until resume; resume continues it; abandon stops it at once and is refused while a worker still writes, so pause first; set_budget sets one node's budget as a positive token count or null for unlimited, and a finite cap must cover the node's context reservation; steer injects a message into the turn running on a node; stop_node interrupts one graph node and pauses its queue. Every action records its reason; abandoning work the user still expects is never right. Resuming work paused by archive needs the current user message ID and an exact quotation.", Parameters: tbObject([]tbField{{"action", tbUnionLiteral([]string{"pause", "resume", "abandon", "set_budget", "steer", "stop_node"})}, {"taskId", tbOptional(tbString(nil))}, {"sourceMessageId", tbOptional(tbString(nil))}, {"instruction", tbOptional(tbString(nil))}, {"nodeId", tbOptional(tbString(nil))}, {"text", tbOptional(tbString(nil))}, {"tokens", tbOptional(tbUnion([]any{tbNumber(), map[string]any{"type": "null"}}))}, {"reason", tbOptional(tbString(nil))}, {"requestId", tbString(nil)}}, []string{"action", "requestId"}), Available: main && features.Supervisor != nil && features.Supervisor.ControlTask},
	}
}
